import{z as l,x as p,o as s,c,q as t,j as i,D as e,d as E,s as n,S as B,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"容器逃逸","description":"","frontmatter":{"title":"容器逃逸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-escape.md","filePath":"cs/container-escape.md","lastUpdated":1791063341000}'),d={name:"cs/container-escape.md"};function A(h,a,m,u,D,C){const o=p("Mermaid");return s(),c("div",null,[a[2]||(a[2]=t('<h1 id="容器逃逸" tabindex="-1">容器逃逸 <a class="header-anchor" href="#容器逃逸" aria-label="Permalink to &quot;容器逃逸&quot;">​</a></h1><div class="epigraph"><p>容器用命名空间与 cgroup 切片同一内核。逃逸常走挂载、特权、有缺陷的系统调用或运行时。比 VM 更轻，也更依赖内核正确与禁止特权容器。</p><footer>—— 据 Linux namespaces/cgroups 文档；OCI 运行时规范；对照[隔离与沙箱](/cs/isolation-sandbox)</footer></div><p>上一课<a href="/cs/vm-escape">VM 逃逸</a>里的客机至少有独立内核；本课缺口是<strong>共享内核的薄盒</strong>——容器与宿主机跑同一个内核，隔离只靠命名空间与 cgroup 这层软件切片。本课讲运行时合同：非特权、只读根、seccomp，不给逃逸步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>容器的经典暴露面：--privileged 关掉全部防护；把宿的 docker.sock 挂进容器等于把宿的管理权递进去；旧版 runc 的漏洞是运行时自身的窗口。缺口是四件默认：容器默认非特权（裁掉 capability）、根文件系统只读、启用用户命名空间把容器 root 映射成宿上的普通用户、镜像最小化少带可利用代码。</p><h3 id="k8s" tabindex="-1">K8s <a class="header-anchor" href="#k8s" aria-label="Permalink to &quot;K8s&quot;">​</a></h3><p>K8s 层面是同一份合同的编排化：准入控制（原 Pod 安全策略，今 Pod Security Standards）把「禁特权、禁宿路径挂载」变成集群级强制，不靠每个开发者自觉。</p><p><span class="marginnote">runc CVE 仅作窗口点名。禁止逃逸教程。隐私单元下一课从差分隐私起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法先对照 VM：VM 的 TCB 是 hypervisor，容器的 TCB 是整个内核——面大得多，默认就必须更严。禁止项清单：特权容器、宿 docker.sock、hostPath 挂载、CAP_SYS_ADMIN；配 seccomp 白名单与 AppArmor/SELinux。系统与硬件课序在此封口，下一课序隐私。</p><p><span class="marginnote">TCB（可信计算基）就是「安全成立所依赖的全部代码」的清单：清单里任何一行出漏洞，隔离承诺就跟着破。VM 的清单是 hypervisor 那几十万行；容器的是整个 Linux 内核两千多万行——清单长了几十倍，这就是容器默认必须更严的算术原因。</span></p>',12)),(s(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTR%5B%22%E5%AE%B9%E5%99%A8%E8%BF%9B%E7%A8%8B%22%5D%20--%3E%20KERN%5B%22%E5%90%8C%E4%B8%80%E5%86%85%E6%A0%B8%22%5D%0A%20%20PRIV%5B%22%E7%89%B9%E6%9D%83%E6%88%96%E5%A5%97%E6%8E%A5%E5%AD%97%E6%8C%82%E8%BD%BD%22%5D%20--%3E%20ESC%5B%22%E9%80%83%E5%88%B0%E5%AE%BF%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20POL%5B%22%E9%9D%9E%E7%89%B9%E6%9D%83%20seccomp%20%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20LIM%5B%22%E7%BC%A9%E5%B0%8F%E9%9D%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"机制一句话：薄隔离必须配更严的默认——隔离层越薄，越没有余量吸收配置错误，容器因此是「默认拒绝再加例外」，与 VM「默认放行再收紧」方向相反。内核漏洞是这个模型的硬边界：共享内核意味着内核 0-day 时容器与宿同沉浮，这正是 gVisor 一类用户态内核与微虚机存在的理由。隐私课序问数据发布而非逃逸。",-1)),(s(),i(B,null,{default:e(()=>[n(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20VMP%5B%22%E8%99%9A%E6%8B%9F%E6%9C%BA%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20G%5B%22%E5%AE%A2%E6%9C%BA%E5%86%85%E6%A0%B8%E5%87%BA%E6%BC%8F%E6%B4%9E%22%5D%20--%3E%20HYP%5B%22%E5%85%88%E5%9B%B0%E5%9C%A8%20hypervisor%20%E8%BF%99%E5%B1%82%22%5D%0A%20%20%20%20HYP%20--%3E%20R1%5B%22%E5%AE%BF%E4%BB%8D%E9%9A%94%E7%9D%80%E4%B8%80%E9%81%93%E5%A2%99%22%5D%0A%20%20end%0A%20%20subgraph%20CTP%5B%22%E5%AE%B9%E5%99%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20P%5B%22%E5%AE%B9%E5%99%A8%E8%BF%9B%E7%A8%8B%E8%A7%A6%E5%8F%91%E5%86%85%E6%A0%B8%E6%BC%8F%E6%B4%9E%22%5D%20--%3E%20K%5B%22%E6%BC%8F%E6%B4%9E%E5%B0%B1%E5%9C%A8%E5%85%B1%E4%BA%AB%E5%86%85%E6%A0%B8%E9%87%8C%22%5D%0A%20%20%20%20K%20--%3E%20R2%5B%22%E5%AE%BF%E7%9B%B4%E6%8E%A5%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">直觉类比：VM 是每户一栋独立小楼，楼与楼之间是护城河（hypervisor）；容器是同一栋楼里用隔断墙隔出的房间。隔断（命名空间）做得再精致，地基（内核）一塌，所有房间一起塌——gVisor 一类方案相当于给房间自建一个假地基。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零逃逸配方；边界要点名：seccomp 与只读根防的是容器攻宿，不防容器之间互打——跨租户还要网络策略与每工作负载的身份。下一课序差分隐私。</p><p><span class="marginnote">常见误区：配好 seccomp、只读根、非特权，就容易以为「这台容器已经攻不破」。实际这套合同只防「容器攻宿」这一个方向；两个容器之间互打走的是网络与身份，要另配网络策略和每负载身份，漏配这层，横向移动照样发生。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VM 有客核；容器共享内核。</li><li>特权与运行时套接字是经典面。</li><li>默认非特权加 seccomp。</li><li>下一课序：差分隐私。</li><li>出处：Linux namespaces；OCI；<a href="/cs/isolation-sandbox">isolation-sandbox</a>。</li></ul>',6))])}const P=l(d,[["render",A]]);export{f as __pageData,P as default};
